  /* ---------- Normen-Ersetzung zur Laufzeit (Quelldaten bleiben BW) ---------- */
  // BW-Paragraf -> Normtyp (siehe Recherche_16-Laender_2026-09-29.md §2 / Laender-Mapping "BW"-Spalten).
  var CITE_RE = /§{1,2}\s*\d+[a-zA-Z]?(?:\s*Abs\.\s*\d+[a-zA-Z]?(?:\s*[,\-–]\s*\d+[a-zA-Z]?)*)?(?:\s*(?:S\.|Satz)\s*\d+(?:\s*[,\-–]\s*\d+)*)?(?:\s*Nr\.\s*\d+[a-zA-Z]?(?:\s*[,\-–]\s*\d+[a-zA-Z]?)*)?(?:\s*,\s*§{0,2}\s*\d+[a-zA-Z]?(?:\s*Abs\.\s*\d+[a-zA-Z]?)?)*\s*PolG\s*BW/g;
